<script setup>
import {computed,nextTick,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {Bell,Settings,ArrowLeft,RefreshCw,X} from '@lucide/vue';
import MobileNotificationRow from './MobileNotificationRow.vue';
const props=defineProps({request:{type:Function,required:true},workspaceId:[Number,String],startInSettings:Boolean,visible:{type:Boolean,default:true},preferences:Object});
const emit=defineEmits(['close','open','changed']);
const items=ref([]),agencies=ref([]),catalog=ref([]),loading=ref(false),saving=ref(null),error=ref(''),settings=ref(props.startInSettings),status=ref('unread'),page=ref(1),totalPages=ref(1),search=ref(''),feedSearch=ref(''),agencyId=ref('all'),sort=ref('newest'),detail=ref(null),notice=ref(''),undo=ref(null),snoozeValue=ref('');
let version=0,noticeTimer,searchTimer,previousFocus,previousOverflow=null,loadedScope='';
function unlockBody(){if(previousOverflow!==null){document.body.style.overflow=previousOverflow;previousOverflow=null;}}
watch(detail,value=>{if(value){if(previousOverflow===null)previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';}else unlockBody();});const cache=new Map();
const unread=n=>!(n._is_read_for_viewer ?? n.viewer_is_read ?? n.is_read);
const key=()=>[props.workspaceId,settings.value,status.value,page.value,agencyId.value,sort.value,feedSearch.value].join(':');
const types=computed(()=>catalog.value.filter(entry=>entry.recommendedForRole&&`${entry.label} ${entry.categoryLabel}`.toLowerCase().includes(search.value.toLowerCase())));
const agencyName=n=>agencies.value.find(a=>Number(a.id)===Number(n.agency_id))?.name || n.agency_name || '';
const sourceLabel=n=>({communication_conversation:'Open email',chat_thread:'Open message',task:'Open task',client:'Open profile'}[n.related_entity_type] || '');
async function load(force=false){const current=++version,scope=key(),cached=cache.get(scope);if(scope!==loadedScope){items.value=cached?.items || [];loadedScope=scope;}if(!force && cached && Date.now()-cached.at<60000){items.value=cached.items;totalPages.value=cached.totalPages;loading.value=false;return;}loading.value=true;error.value='';try{
 const params=new URLSearchParams({status:status.value,page:String(page.value),agencyId:agencyId.value,sort:sort.value,...(feedSearch.value?{search:feedSearch.value}:{})});
 const data=await props.request('GET',settings.value?'/notification-settings':`/notification-feed?${params}`);
 if(current!==version)return;
 if(settings.value)catalog.value=data.types || [];else{items.value=data.items || [];agencies.value=data.agencies || agencies.value;totalPages.value=data.pagination?.totalPages || 1;cache.set(scope,{items:items.value,totalPages:totalPages.value,at:Date.now()});if(cache.size>8)cache.delete(cache.keys().next().value);}
}catch(e){if(current===version){if([401,403,423].includes(e.response?.status)){cache.clear();items.value=[];}error.value=e.response?.data?.error?.message || 'Notifications could not load. Please try again.';}}finally{if(current===version)loading.value=false;}}
function announce(text){notice.value=text;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>{notice.value='';undo.value=null;},5000);}
async function state(item,patch,{recordUndo=true}={}){
 if(saving.value)return;const scope=key(),previous={...item},before=[...items.value],requestVersion=version;saving.value=item.id;error.value='';
 if(patch.read!==undefined){item.is_read=patch.read;item._is_read_for_viewer=patch.read;item.viewer_is_read=patch.read;}
 if(patch.dismissed!==undefined)item.dismissed_at=patch.dismissed?new Date().toISOString():null;
 if(patch.snoozedUntil!==undefined)item.snoozed_until=patch.snoozedUntil;
 const hidden=status.value==='unread' && !unread(item) || status.value==='read' && unread(item) || status.value==='dismissed' && !item.dismissed_at || status.value!=='dismissed' && item.dismissed_at || status.value==='snoozed' && (!item.snoozed_until || new Date(item.snoozed_until)<=new Date()) || status.value!=='snoozed' && item.snoozed_until && new Date(item.snoozed_until)>new Date();
 if(hidden)items.value=items.value.filter(n=>n.id!==item.id);cache.clear();
 try{await props.request('PATCH',`/notification-feed/${item.id}`,patch);if(requestVersion!==version)return;if(recordUndo)undo.value={item:previous,patch:{read:!unread(previous),dismissed:!!previous.dismissed_at,snoozedUntil:previous.snoozed_until || null}};announce(patch.dismissed?'Notification deleted':patch.snoozedUntil?'Notification snoozed':patch.dismissed===false?'Notification restored':patch.read?'Marked as read':'Marked as unread');cache.clear();cache.set(scope,{items:[...items.value],totalPages:totalPages.value,at:Date.now()});emit('changed');}
 catch(e){if([401,403,423].includes(e.response?.status)){cache.clear();items.value=[];detail.value=null;}else if(scope===key()){for(const field of Object.keys(item))if(!(field in previous))delete item[field];Object.assign(item,previous);items.value=before;cache.clear();}error.value=e.response?.data?.error?.message || 'This notification could not be updated. Try again.';undo.value=null;emit('changed');}
 finally{saving.value=null;}
}
function action(item,value){if(['delete','restore'].includes(value)){detail.value=null;return state(item,{dismissed:value==='delete'});}if(value==='read'||value==='unread')return state(item,{read:value==='read'});}
async function undoAction(){const saved=undo.value;if(!saved)return;undo.value=null;await state(saved.item,saved.patch,{recordUndo:false});if(!error.value)await load(true);}
async function toggle(entry){saving.value=entry.type;error.value='';try{await props.request('PATCH',`/notification-settings/${encodeURIComponent(entry.type)}`,{inApp:!entry.effective.inApp});cache.clear();await load(true);}catch(e){error.value=e.response?.data?.error?.message || 'Your notification preference could not be saved.';}finally{saving.value=null;}}
async function preview(item){previousFocus=document.activeElement;detail.value=item;snoozeValue.value='';await nextTick();document.querySelector('[aria-label="Notification details"] button')?.focus();if(unread(item))void state(item,{read:true});}
function closeDetail(){detail.value=null;previousFocus?.focus?.({preventScroll:true});}
function trap(event){if(event.key!=='Tab')return;const nodes=[...event.currentTarget.querySelectorAll('button:not(:disabled),input:not(:disabled)')];if(event.shiftKey&&document.activeElement===nodes[0]){event.preventDefault();nodes.at(-1)?.focus();}else if(!event.shiftKey&&document.activeElement===nodes.at(-1)){event.preventDefault();nodes[0]?.focus();}}
function snooze(item,until){detail.value=null;return state(item,{snoozedUntil:until});}
function customSnooze(){const value=new Date(snoozeValue.value);if(!Number.isFinite(value.getTime())||value<=new Date()){error.value='Choose a future snooze time.';return;}return snooze(detail.value,value.toISOString());}
function reset(){if(page.value!==1)page.value=1;else void load();}
watch([settings,status,agencyId,sort,()=>props.workspaceId],reset);watch(page,()=>load());watch(feedSearch,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(reset,300);});watch(()=>props.startInSettings,value=>{settings.value=!!value;});watch(()=>props.visible,value=>{if(value)void load();else{detail.value=null;undo.value=null;}});onMounted(load);onBeforeUnmount(()=>{version++;unlockBody();cache.clear();clearTimeout(noticeTimer);clearTimeout(searchTimer);});
</script>
<template>
 <section class="mobile-notifications" aria-label="Notifications">
  <header><button type="button" aria-label="Back to workspace" @click="emit('close')"><ArrowLeft :size="22"/></button><h1><Bell :size="21"/>{{settings?'Notification settings':'Notifications'}}</h1><button type="button" :aria-label="settings?'View notifications':'Notification settings'" @click="settings=!settings"><Settings :size="22"/></button></header>
  <p v-if="settings" class="help">Choose which updates appear in Notifications. Turning an alert off keeps its email in Conversa. Device push permissions are managed in My Account.</p>
  <div class="controls"><input v-if="settings" v-model="search" type="search" aria-label="Search notification settings" placeholder="Search notification types"/><template v-else><select v-model="status" aria-label="Notification status"><option value="unread">Unread</option><option value="all">All active</option><option value="read">Read</option><option value="snoozed">Snoozed</option><option value="dismissed">Deleted</option></select><select v-model="agencyId" aria-label="Notification agency"><option value="all">All agencies</option><option v-for="a in agencies" :key="a.id" :value="String(a.id)">{{a.name}}</option></select><select v-model="sort" aria-label="Notification sort"><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="priority">Priority</option></select><input v-model="feedSearch" type="search" aria-label="Search notifications" placeholder="Search notifications"/></template><button type="button" aria-label="Refresh notifications" :disabled="loading" @click="load(true)"><RefreshCw :size="20"/></button></div>
  <p v-if="error" role="alert">{{error}} <button @click="load(true)">Try again</button></p><p v-if="notice" role="status" class="notice">{{notice}} <button v-if="undo" :disabled="saving!==null" @click="undoAction">Undo</button></p><p v-if="loading&&!items.length" role="status">Loading…</p>
  <template v-if="settings"><article v-for="entry in types" :key="entry.type" class="setting"><span><strong>{{entry.label}}</strong><small>{{entry.categoryLabel}}{{entry.locked?' · '+entry.lockReason:''}}</small></span><button type="button" role="switch" :aria-checked="entry.effective.inApp" :aria-label="`${entry.label} in-app alerts`" :disabled="entry.locked||saving===entry.type" @click="toggle(entry)">{{entry.effective.inApp?'On':'Off'}}</button></article></template>
  <template v-else><p v-if="!loading&&!error&&!items.length">No {{status==='unread'?'unread ':''}}notifications in this view.</p><MobileNotificationRow v-for="item in items" :key="item.id" :item="item" :unread="unread(item)" :agency-name="agencyName(item)" :preferences="preferences" :disabled="saving!==null" @open="preview" @options="preview" @action="action"/><footer v-if="totalPages>1"><button :disabled="page===1" @click="page--">Previous</button><span>Page {{page}} of {{totalPages}}</span><button :disabled="page===totalPages" @click="page++">Next</button></footer></template>
  <Teleport to="body"><div v-if="detail && visible" class="notification-detail-overlay" @click.self="closeDetail"><section role="dialog" aria-modal="true" aria-label="Notification details" @keydown.esc="closeDetail" @keydown="trap"><button class="detail-close" aria-label="Close notification details" @click="closeDetail"><X :size="22"/></button><h2>{{detail.title}}</h2><small>{{agencyName(detail)}} · {{new Date(detail.created_at).toLocaleString()}}</small><p class="full-message">{{detail.message}}</p><p v-if="error" role="alert">{{error}}</p><div class="actions"><button v-if="sourceLabel(detail)" @click="emit('open',detail)">{{sourceLabel(detail)}}</button><button :disabled="saving!==null" @click="state(detail,{read:unread(detail)})">{{unread(detail)?'Mark read':'Mark unread'}}</button><button :disabled="saving!==null" @click="action(detail,detail.dismissed_at?'restore':'delete')">{{detail.dismissed_at?'Restore':'Delete'}}</button><button :disabled="saving!==null" @click="snooze(detail,new Date(Date.now()+3600000).toISOString())">Snooze 1 hour</button><button v-if="detail.snoozed_until" :disabled="saving!==null" @click="state(detail,{snoozedUntil:null})">End snooze</button></div><label class="snooze">Snooze until<input v-model="snoozeValue" type="datetime-local"/></label><button :disabled="saving!==null || !snoozeValue" @click="customSnooze">Set snooze</button></section></div></Teleport>
 </section>
</template>
<style scoped>
.mobile-notifications{position:fixed;inset:0;z-index:2600;background:#f6f8fb;color:#203348;overflow:auto;padding:env(safe-area-inset-top) 12px calc(24px + env(safe-area-inset-bottom));box-sizing:border-box;font:14px/1.5 system-ui}.mobile-notifications header{position:sticky;top:0;display:flex;align-items:center;gap:10px;background:#f6f8fb;padding:12px 0;border-bottom:1px solid #dce3eb;z-index:3}.mobile-notifications h1{font-size:19px;display:flex;align-items:center;gap:8px;flex:1;margin:0}.mobile-notifications button,.mobile-notifications select,.mobile-notifications input{min-height:40px;border:1px solid #ccd7e2;border-radius:8px;background:white;color:inherit;padding:8px;font:inherit;box-sizing:border-box}.mobile-notifications select,.mobile-notifications input{font-size:16px}.controls,.actions,footer{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:12px 0}.controls input{flex:1 1 100%;min-width:0}.controls select{flex:1;min-width:0;max-width:100%}.setting{background:#fff;border:1px solid #dce3eb;border-radius:12px;margin:12px 0;padding:16px;display:flex;align-items:center;justify-content:space-between;gap:14px}.setting small{display:block;margin-top:6px}.setting [aria-checked=true]{background:#246d60;color:white}.help,small{color:#52657a;line-height:1.5}button:disabled{opacity:.55}footer{justify-content:space-between}.notice{background:#e8f4ef;padding:8px 12px;border-radius:8px;font-size:12px}.notice button{border:0;background:transparent;color:#2456ba}.notification-detail-overlay{position:fixed;inset:0;z-index:2700;background:#18334e88;display:grid;place-items:center;padding:14px;box-sizing:border-box;color:#203348;font:14px/1.5 system-ui}.notification-detail-overlay section{background:white;border-radius:16px;padding:18px;max-height:88dvh;overflow:auto;max-width:650px;width:100%;box-sizing:border-box}.notification-detail-overlay h2{font-size:17px;overflow-wrap:anywhere;margin:10px 0}.notification-detail-overlay button{font:inherit;border:1px solid #ccd7e2;border-radius:8px;padding:9px;background:#f5f8ff;color:#254a80;min-height:42px}.detail-close{float:right}.full-message{white-space:pre-wrap;overflow-wrap:anywhere;clear:both}.snooze{display:grid;gap:6px;font-size:12px;margin:10px 0}.snooze input{font:16px system-ui;padding:10px;border:1px solid #ccd7e2;border-radius:8px;max-width:100%;box-sizing:border-box}
</style>
